// Runs qdef-lint.cjs (vendored from mofosyne/qdef's prototype, see that file's own header)
// — an independent, standalone QDEF grammar/footgun checker sharing no code with any of
// TagDrop's own encoders — against every code test-qdef-roundtrip.mjs's own encoder
// produced (tools/qdef-fixtures.json, regenerated by `npm run test:qdef`). A second,
// independently-written check on top of this project's own test suites: this file's own
// canonical-map-key-order check would have caught SPEC.md v12's key-ordering bug directly.
// None of TagDrop's carriers use QDEF's magic header (own URI scheme / NFC MIME type
// already dispatch, SPEC.md §2), so every code is linted with --no-magic (hasMagic: false).
import { readFileSync } from 'node:fs';
import { lintRootBytes } from './qdef-lint.cjs';

const fixtures = JSON.parse(readFileSync(new URL('./qdef-fixtures.json', import.meta.url)));

let codeCount = 0;
let failed = false;

for (const fixture of fixtures) {
  if (!fixture.codes) continue; // tamper-detection fixtures intentionally carry no codes
  for (const hex of fixture.codes) {
    codeCount++;
    const buf = Buffer.from(hex, 'hex');
    const findings = lintRootBytes(buf, { hasMagic: false });
    const errors = findings.filter((f) => f.severity === 'error');
    const warnings = findings.filter((f) => f.severity === 'warning');
    if (errors.length > 0 || warnings.length > 0) {
      failed = true;
      console.log(`--- ${fixture.name} (${buf.length} bytes) ---`);
      for (const f of findings) {
        console.log(`  ${f.severity.toUpperCase().padEnd(7)} [${f.code}] @${f.pos}: ${f.message}`);
      }
    }
  }
}

if (failed) {
  console.log();
  console.log('qdef-lint found error(s)/warning(s) — see above.');
  process.exit(1);
}

console.log(`qdef-lint: ${codeCount} code(s) across ${fixtures.length} fixtures — clean (0 errors, 0 warnings).`);
